function prepaidOffice_Check()
{
	try
	{
		document.getElementById("btn_t10save").disabled = false;
		var prepaid = document.getElementsByName("frm_p_t10sheet3_ofc_cd")[0].value;
		var blpref = document.getElementById("frm_t10sheet1_bkg_no").value.substr(0,2);
		var preOfc = "";
		
		if(blpref == "TA")
		{
			preOfc = "TAOBB";
		}
		else if(blpref == "TS")
		{
			preOfc = "TSNBB";
		}
		else if(blpref == "DL")
		{
			preOfc = "DLCBB"
		}
		else if(blpref == "LY")
		{
			preOfc = "LYGBB"
		}
		else if(blpref == "NB")
		{
			preOfc = "NBOBB";
		}
		else if(blpref == "SH")
		{
			preOfc = "SHABB";
		}
		else if(blpref == "CK")
		{
			preOfc = "CKGBB";
		}
		else if(blpref == "NK")
		{
			preOfc = "NKGBB"
		}
		else if(blpref == "WU")
		{
			preOfc = "WUHBB";
		}
		
		if(prepaid != preOfc)
		{
			for(var i = 0; i < 2; i ++)
			{
				let comment = prompt("Prepaid Office does not match with BL Prefix.\r\n1. As per SI request\r\n2. Direct Booking\r\n3. Wrong Payment Office");
				if (comment == null)
				{
					i = -1;
				}
				else
				{
					if(comment.trim().toLowerCase() == "wrong payment office")
					{
						alert("Please update prepaid office accordingly");
						document.getElementById("btn_t10save").disabled = true;
						break;
					}
					else if(comment.trim().toLowerCase() == "as per si request" || comment.trim().toLowerCase() == "direct booking")
					{
						document.getElementById("btn_t10save").disabled = false;
						break;
					}
					else
					{
						alert("Please enter valid comment (As per SI request / Direct Booking / Wrong Payment Office)");
						i = -1;
					}
				}
			}
		}
	}
	catch(err)
	{
		
	}
}

