function BLTypeAndNumber()
{
	try
	{
		var BDCType = document.getElementById("bl_ready_type_text").value;
		var BITypeCode = document.getElementById("frm_t11sheet1_bl_iss_tp_cd").value;
		var BITypeName = document.getElementById("bl_issuebl_type_text").value;
		var BITypeNo = document.getElementById("frm_t11sheet1_bl_issue_no").value;
		var eBLFlag = document.getElementById("ebl_flg_checkbox").checked;
		var flag = 0;
		
		
		//BDC type mismatch with BL Issue
		if(BDCType != BITypeCode)
		{
			flag = 1;
		}
		else if(BITypeCode == "B")
		{
			//BL Issue OBL
			//eBL Tick and BLIssue not OBL or not 1
			if(eBLFlag == true && (BITypeName != "Original B/L" || BITypeNo != "1"))
			{
				flag = 1;
			}
			else if(eBLFlag == false && (BITypeName != "Original B/L" || BITypeNo != "3"))
			{
				flag = 1;
			}
			else
			{
				flag = 0;
			}
		}
		else if(BITypeCode == "W")
		{
			//BL Issue SWB
			if(BITypeName != "Sea Waybill" || BITypeNo != "1")
			{
				flag = 1;
			}
			else
			{
				flag = 0;
			}
		}
		
		if(flag == 1)
		{
			document.getElementById("btn_t11Save").setAttribute("disabled","true");
		}
		else
		{
			document.getElementById("btn_t11Save").removeAttribute("disabled");
		}
	}
	catch(err){ }
}

