function validateCustomerRatesAs() //Sunil
{
    try
    {
        let scNo = document.getElementById("frm_t10sheet1_sc_no1").value.trim();
        let rfaNo = document.getElementById("frm_t10sheet1_rfa_no").value.trim();
        let taaNo = document.getElementById("frm_t10sheet1_taa_no").value.trim();

        let saveButton = document.getElementById("btn_t10save");

        let validCustomer = false;

		if (scNo == "SHAB01757A" || scNo == "SHA0040B26" || rfaNo == "SHAB01757A" || rfaNo == "SHA0040B26" || taaNo == "SHAB01757A" || taaNo == "SHA0040B26" )
        {
            validCustomer = true;
        }

        if (validCustomer == false)
        {
            saveButton.disabled = false;
            return;
        }

        let ratedRows = document.getElementsByClassName("GMWrap0 GMAlignRight GMFloat GMCell IBSheetFont1 HideCol1C10");
        let inRows = document.getElementsByClassName("GMWrap0 GMAlignCenter GMText GMCell IBSheetFont1 HideCol1C16");

        saveButton.disabled = false;

        for (let i = 0; i < ratedRows.length; i++)
        {
            let ratedValue = ratedRows[i].innerText.trim();
            let inValue = inRows[i].innerText.trim();

            if (inValue == "N")
            {
                let number = parseFloat(ratedValue);

                if (number % 1 != 0)
                {
                    alert("For IKEA customer, Rated As must contain only whole (Not Decimal) values when IN column is N and I.");
					saveButton.disabled = true;
					return;
                }
            }
        }
        saveButton.disabled = false;
    }
    catch(err)
    {}
}


function GB_CPF_Selection() {
	try {
		const pod = document.getElementsByName("pod_cd")[0].value;
		const del = document.getElementsByName("del_cd")[0].value;

		const parties = {
			"Consignee": document.getElementsByName("cn_cust_lgl_eng_nm")[0].value,
			"Notify Party": document.getElementsByName("nf_cust_lgl_eng_nm")[0].value,
			"A/Notify Party": document.getElementsByName("an_cust_lgl_eng_nm")[0].value
		};

		const company = "OCEAN NETWORK EXPRESS (EUROPE)";
		const cpfCode = "GB500253";

		if (pod.startsWith("GB") || del.startsWith("GB")) {
			for (const [partyName, partyValue] of Object.entries(parties)) {
				if (partyValue.startsWith(company)) {
					prompt(`Use CPF code ${cpfCode} for ${partyName} instead of dummy code`, cpfCode);
				}
			}
		}
	} catch (err) { }

}